    title: 'Home - My Blog',
  },
}

interface Post {
  id: number
  title: string
}

async function getPosts(): Promise<Post[]> {
  const res = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
